var u = source.key;
var tagUrl = u + "/sort.html";
var tag = java.ajax(tagUrl);
var tagList = org.jsoup.Jsoup.parse(tag).select(".content ul li a");
var tagSize = 0.4;
push("分类", null, 1);
for (var i = 0; i < tagList.length - 1; i++) {
var title = tagList[i].text();
var url = source.key + String(tagList[i].attr("href")).replace(/(\d+)(?!.*\d)/, "{{page}}");
title = String(title).replace(/\s/g, "");
push(title, url, tagSize);
}
var spaceLength = tagList.length % 2;
for (i = 0; i < spaceLength; i++) {
push("{{——}}", null, tagSize);
}
JSON.stringify(result);

