@js:
eval(String(source.loginUrl));
let Cookie = cookie.getCookie(GetUL());
if (!/lf_user_auth/.test(Cookie) && source.getLoginHeader()) {
    let ck = source.getLoginHeaderMap()['Cookie']
    cookie.setCookie(GetUL(), ck);
    java.toast('登录状态掉了，已重新登陆');
}
var result = [];
var headers = JSON.stringify({"headers":{"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/121.0.6167.171 Safari/537.36"}});
var push = (title, url, size) =>
    result.push({
        title: title,
        url: url ? `{{GetUL()}}${url},` + headers : url,
        style: {
            layout_flexGrow: 1,
            layout_flexBasisPercent: size
        }
    });
push(`当前站源：${GetUL()}`, null, 1)
if (source.getLoginHeader()) {
    let jc = source.getLoginHeaderMap();
    let inf = decodeURIComponent(jc.get("Cookie"));
    let info = decodeURIComponent(inf).match(/\{[\s\S]+\}/)[0];
    let username = JSON.parse(info)['username'];
    let expe = Ajax(`${GetUL()}/user/index/index.html`);
    let ex = org.jsoup.Jsoup.parse(expe).select('.group , .user-data li');
    push(`用户◎${username}◎中心`, null, 1);
    push("书架", "/user/bookshelf?page={{page}}", 0.45);
    push("阅读记录", "/user/recentread/index.html", 0.45);
    ex.forEach(xp => {
        nam = String(xp.text()).replace(/[^\u4e00-\u9fa5a-zA-Z0-9]/g, "");
        title = /\d/.test(nam) ? nam.replace(/(\d+)([^\d]+)/, "$2：$1") : nam.replace(/^/, "用户等级：");
        push(title, null, 0.45);
    });
} else {
    push("未登录", null, 1);
}
push("--------书库--------", null, 1);
push("最近更新", "/all{{Sort_()}}.html", 0.45);
push("原创", "/original.html?page={{page}}", 0.45);
push("排行", null, 1);
var src = Ajax(`${GetUL()}/all/order/hits+desc.html`);
var ph = org.jsoup.Jsoup.parse(src).select('.paihang_ds a');
ph.forEach(ta => {
    nam = ta.text();
    ul = ta.attr('href')
    push(nam, ul, 0.45);
})
push("分类", null, 1);
var tag = org.jsoup.Jsoup.parse(src).select('.fenlei_ds a');
tag.forEach(ta => {
    nam = ta.text();
    ul = String(ta.attr('href')).replace(/$/, "?page={{page}}").replace(/lists/, "all/id").replace(/\.html/, `{{Sort_()}}$&`);
    push(nam, ul, 0.25);
})
if (source.getLoginInfoMap()?.["发现自定义标签🏷️（中 / 英逗号分隔）"] != "") {
	   push("自定义标签🏷️", null, 1);
	   let myTags = String(source.getLoginInfoMap()["发现自定义标签🏷️（中 / 英逗号分隔）"]).split(/[,，]/);
	   myTags.forEach(tag => {
	   	let url = `/search.html?q=${tag}&f=tag&sort={{Sort_('search')}}&p={{page}}&serialize=`;
	   	push(tag, url, 0.25);
	   	});
}
JSON.stringify(result);

source.jsLib:
function calculateChecksum(nonce, cookieString) {
    var cpk = "ge_ua_p";
    if (!cookieString || !nonce) {
        return null;
    }
    var cookieValue = "";
    var cookieArray = cookieString.toString().split(";");
    for (var i = 0; i < cookieArray.length; i++) {
        var cookie = cookieArray[i].trim();
        var parts = cookie.split("=");
        if (parts.length === 2 && parts[0] === cpk) {
            cookieValue = parts[1];
            break;
        }
    }
    if (cookieValue.length === 0) {
        return null;
    }
    var sum = 12345;
    for (var i = 0; i < cookieValue.length; i++) {
        var char = cookieValue[i];
        if (/^[a-zA-Z0-9]$/.test(char)) {
            sum += cookieValue.charCodeAt(i) * (nonce + i);
        }
    }
    return {
    	"body": "sum=" + sum + "&nonce=" + nonce,
    	"cookieValue": cookieValue
    	};
}

function Check_(src, cookies = null, url) {
    const { java } = this;
    if (!/Checking your browser/.test(src)) return src;
    java.toast('检测到验证，正在自动处理中……');
    let nonce = parseInt(src.match(/nonce\s*=\s*(\d+)/)[1]);
    cookies = String(cookies);
    let data = calculateChecksum(nonce, cookies);
    let headers = {
        "User-Agent": "Mozilla/5.0 (Android 11; Mobile; rv:140.0) Gecko/140.0 Firefox/140.0",
        "Content-Type": "application/x-www-form-urlencoded",
        "Referer": String(this.GetUL() + "/"),
        "X-Ge-Ua-Step": "prev",
        "Cookie": String("ge_ua_p=" + data.cookieValue)
    };
    let postResponse = java.post(this.GetUL(), data.body, headers);
    let success = JSON.parse(postResponse.body()).ok;
    java.toast(success ? '验证通过' : '验证失败，请重试！');
    if (!success) return src;
    return java.ajax(url);
}

function Sort_(t) {
	   const { source } = this
    const sgvs = JSON.parse(source.getVariable())?.s || 0;
    if (!sgvs) return t === 'search' ? 'relevance' : '';
