ruleContent.content:
@js:
var url = GetUL();
var nn = String(cookie.getCookie(url));
var coks = nn.split('; ');
var ckk = coks.filter(item => !item.startsWith("lf_reader_num")).join('; ');
cookie.setCookie(url, ckk);
const chapterul = java.hexDecodeToString(src);
function content() {
    let html = java.ajax(chapterul);
    let content = String(java.getString('.content_txt@html', html));
    return content.includes('正在获取小说信息') ? (eval('bookdata = ' + html.match(/book\.initial\s*=\s*({[\s\S]+?};)/)[1]),getContent(bookdata)) : content;
}
const text = content().trim();
let retryCount = 0;
const maxRetries = 3;
let result;
while (retryCount < maxRetries) {
    if (text != "" && !/正在加载小说中,请稍后/.test(text)) {
        result = text;
        break;
    } else {
        retryCount++;
        java.toast(`\n未获取到文本，正在重试...\n（当前第${retryCount} / ${maxRetries}次重试）`);
        text = content();
    }
}
if (retryCount === maxRetries) {
    result = "重试三次仍未获取到文本，请检查网络状况。";
}
result;

